import React, { useState } from 'react';
import { MOCK_LISTINGS, BRAND } from '../constants';
import { MapPin, Bed, Bath, Square, ExternalLink } from 'lucide-react';

const ListingGrid: React.FC<{ limit?: number }> = ({ limit }) => {
  const [filter, setFilter] = useState('All');
  const cities = ['All', ...new Set(MOCK_LISTINGS.map(l => l.city))];

  const displayedListings = MOCK_LISTINGS
    .filter(l => filter === 'All' || l.city === filter)
    .slice(0, limit || MOCK_LISTINGS.length);

  return (
    <div>
      {!limit && (
        <div className="flex flex-wrap justify-center gap-4 mb-12">
          {cities.map(city => (
            <button
              key={city}
              onClick={() => setFilter(city)}
              className={`px-6 py-2 rounded-full font-medium transition-all ${
                filter === city 
                  ? 'bg-[#00A651] text-white' 
                  : 'bg-white text-gray-600 hover:bg-gray-100 border border-gray-200'
              }`}
            >
              {city}
            </button>
          ))}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {displayedListings.map(listing => (
          <div 
            key={listing.id} 
            className="group bg-white rounded-xl overflow-hidden shadow-md hover:shadow-xl transition-all duration-300 border border-gray-100"
          >
            <div className="relative h-64 overflow-hidden">
              <img 
                src={listing.imageUrl} 
                alt={listing.address} 
                className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
              />
              <div className="absolute top-4 left-4 bg-[#00A651] text-white px-3 py-1 rounded text-sm font-bold">
                {listing.type}
              </div>
              <div className="absolute bottom-4 left-4 bg-[#002366]/90 text-white px-4 py-2 rounded-lg font-bold text-lg">
                ${listing.price.toLocaleString()}
              </div>
            </div>

            <div className="p-6">
              <div className="flex items-start justify-between mb-4">
                <div>
                  <h3 className="font-bold text-lg text-[#002366] group-hover:text-[#00A651] transition-colors">
                    {listing.address}
                  </h3>
                  <div className="flex items-center text-gray-500 text-sm mt-1">
                    <MapPin size={14} className="mr-1" />
                    {listing.city}, AB
                  </div>
                </div>
                <button className="text-gray-400 hover:text-[#00A651]">
                  <ExternalLink size={20} />
                </button>
              </div>

              <div className="grid grid-cols-3 gap-4 py-4 border-t border-gray-100">
                <div className="flex items-center text-gray-600 text-sm">
                  <Bed size={16} className="mr-2 text-gray-400" />
                  {listing.beds} Beds
                </div>
                <div className="flex items-center text-gray-600 text-sm">
                  <Bath size={16} className="mr-2 text-gray-400" />
                  {listing.baths} Baths
                </div>
                <div className="flex items-center text-gray-600 text-sm">
                  <Square size={16} className="mr-2 text-gray-400" />
                  {listing.sqft} sqft
                </div>
              </div>

              <button className="w-full mt-4 py-3 border-2 border-[#002366] text-[#002366] font-bold rounded-lg hover:bg-[#002366] hover:text-white transition-all">
                View Details
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ListingGrid;

import React, { useState, useEffect } from 'react';
import { Menu, X, Phone, Mail } from 'lucide-react';
import { Page } from '../types';

interface NavbarProps {
  currentPage: Page;
  setPage: (page: Page) => void;
}

const Navbar: React.FC<NavbarProps> = ({ currentPage, setPage }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Home', value: Page.Home },
    { name: 'Properties', value: Page.Listings },
    { name: 'Sellers', value: Page.Sellers },
    { name: 'Buyers', value: Page.Buyers },
    { name: 'About', value: Page.About },
    { name: 'Contact', value: Page.Contact },
  ];

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${
      scrolled ? 'bg-white shadow-lg py-3' : 'bg-transparent py-6'
    }`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center">
          {/* Logo */}
          <div 
            className="flex flex-col cursor-pointer" 
            onClick={() => setPage(Page.Home)}
          >
            <span className={`text-2xl font-extrabold tracking-tight ${scrolled ? 'text-[#002366]' : 'text-white'}`}>
              DILLON <span className="text-[#00A651]">ROCHON</span>
            </span>
            <span className={`text-[10px] font-bold uppercase tracking-widest ${scrolled ? 'text-gray-500' : 'text-gray-200'}`}>
              2% Realty Southern Alberta
            </span>
          </div>

          {/* Desktop Nav */}
          <div className="hidden lg:flex items-center space-x-8">
            {navLinks.map((link) => (
              <button
                key={link.name}
                onClick={() => setPage(link.value)}
                className={`font-semibold text-sm transition-colors hover:text-[#00A651] ${
                  currentPage === link.value 
                    ? 'text-[#00A651]' 
                    : scrolled ? 'text-gray-700' : 'text-white'
                }`}
              >
                {link.name}
              </button>
            ))}
            <button 
              onClick={() => setPage(Page.Contact)}
              className="bg-[#00A651] text-white px-6 py-2 rounded-full font-bold text-sm hover:bg-[#008c45] transition-all transform hover:scale-105"
            >
              Free Valuation
            </button>
          </div>

          {/* Mobile toggle */}
          <div className="lg:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className={`${scrolled ? 'text-[#002366]' : 'text-white'}`}
            >
              {isOpen ? <X size={28} /> : <Menu size={28} />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile menu */}
      {isOpen && (
        <div className="lg:hidden bg-white shadow-xl h-screen animate-fade-in">
          <div className="px-4 pt-8 pb-12 space-y-4">
            {navLinks.map((link) => (
              <button
                key={link.name}
                onClick={() => {
                  setPage(link.value);
                  setIsOpen(false);
                }}
                className={`block w-full text-left px-4 py-4 text-xl font-bold border-b border-gray-100 ${
                  currentPage === link.value ? 'text-[#00A651]' : 'text-[#002366]'
                }`}
              >
                {link.name}
              </button>
            ))}
            <div className="pt-6 space-y-4">
              <a href="tel:4035550123" className="flex items-center px-4 text-[#002366] font-semibold">
                <Phone size={20} className="mr-3 text-[#00A651]" /> 403-555-0123
              </a>
              <button 
                onClick={() => {
                  setPage(Page.Contact);
                  setIsOpen(false);
                }}
                className="w-full bg-[#00A651] text-white py-4 rounded-xl font-bold text-lg"
              >
                Request Free Evaluation
              </button>
            </div>
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
