        <a 
          href="tel:4035550123" 
          className="bg-[#002366] text-white p-4 rounded-full shadow-2xl hover:scale-110 transition-transform flex items-center justify-center"
          title="Call Dillon"
        >
          <Phone size={24} />
        </a>
      </div>

      <Footer setPage={handlePageChange} />
    </div>
  );
};

